from pwn import *
import os

# Parse KSH file
def parse_ksh(filename):
    with open(filename, 'r', encoding='utf-8-sig') as f:
        content = f.read()

    # Split metadata and chart data
    metadata, chart = content.split('--\n', 1)

    # Parse metadata
    meta_dict = {}
    for line in metadata.split('\n'):
        if '=' in line:
            key, value = line.split('=', 1)
            meta_dict[key] = value

    return meta_dict, chart

# Connect to server
def connect_server():
    try:
        conn = remote('34.234.204.29', 39079)
        return conn
    except Exception as e:
        print(f"Failed to connect: {e}")
        return None

def main():
    # Parse local flag.ksh
    ksh_path = '/home/ctfplayer/ctf_files/pwnvoltex/flagsong/flag.ksh'
    meta, chart = parse_ksh(ksh_path)
    print("=== KSH Metadata ===")
    for k,v in meta.items():
        print(f"{k}: {v}")

    print("\n=== Attempting server connection ===")
    conn = connect_server()
    if conn:
        try:
            print(conn.recvuntil(b'\n').decode())
            conn.close()
        except:
            print("Failed to receive data")
            conn.close()

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from pwn import *
import time
import json

# Set up logging
context.log_level = 'debug'

def analyze_protocol():
    # Connect to the server
    try:
        conn = remote('34.234.204.29', 39079)

        # Let's try to capture the initial handshake
        print("[+] Connected to server, analyzing handshake...")

        # Send a basic client hello message (trying WebSocket-like format)
        hello = {
            "type": "hello",
            "version": "1.0",
            "name": "analyzer"
        }
        conn.send(json.dumps(hello).encode() + b'\n')

        # Receive and analyze responses
        for i in range(3):  # Try to get a few messages
            try:
                response = conn.recvuntil(b'\n', timeout=2)
                print(f"[+] Received: {response}")

                # Try to parse as JSON
                try:
                    parsed = json.loads(response.decode())
                    print(f"[+] Parsed JSON: {parsed}")
                except:
                    print(f"[+] Raw data (hex):")
                    print(hexdump(response))

            except EOFError:
                print("[-] Connection closed by server")
                break
            except Exception as e:
                print(f"[-] Error receiving data: {e}")
                break

        # Try to request song list or room list
        list_req = {
            "type": "list_rooms"
        }
        conn.send(json.dumps(list_req).encode() + b'\n')

        # Wait for response
        try:
            response = conn.recvuntil(b'\n', timeout=2)
            print(f"[+] Room list response: {response}")
        except:
            pass

        # Try to join/create room
        join_req = {
            "type": "create_room",
            "name": "test_room"
        }
        conn.send(json.dumps(join_req).encode() + b'\n')

        # Wait for response
        try:
            response = conn.recvuntil(b'\n', timeout=2)
            print(f"[+] Create room response: {response}")
        except:
            pass

    except Exception as e:
        print(f"[-] Failed to connect: {e}")
        return

    finally:
        try:
            conn.close()
        except:
            pass

if __name__ == '__main__':
    analyze_protocol()

